CREATE TABLE lick_families(id INTEGER PRIMARY KEY,slug TEXT UNIQUE NOT NULL,name TEXT NOT NULL,canonical_key TEXT,degree_pattern TEXT,analytical_system TEXT NOT NULL,attribution TEXT NOT NULL,attribution_confidence TEXT NOT NULL,review_status TEXT NOT NULL);
CREATE TABLE lick_source_phrases(id INTEGER PRIMARY KEY,slug TEXT UNIQUE NOT NULL,source_package_id INTEGER NOT NULL REFERENCES source_packages(id),source_file_id INTEGER NOT NULL REFERENCES source_files(id),source_hash TEXT NOT NULL,track_name TEXT NOT NULL,measure_start INTEGER NOT NULL,measure_end INTEGER NOT NULL,provenance TEXT NOT NULL,review_status TEXT NOT NULL);
CREATE TABLE lick_versions(id INTEGER PRIMARY KEY,slug TEXT UNIQUE NOT NULL,family_id INTEGER NOT NULL REFERENCES lick_families(id),source_phrase_id INTEGER NOT NULL REFERENCES lick_source_phrases(id),version_kind TEXT NOT NULL,key_name TEXT NOT NULL,meter TEXT NOT NULL,tempo REAL,phrase_length REAL NOT NULL,review_status TEXT NOT NULL);
CREATE TABLE lick_version_notes(id INTEGER PRIMARY KEY,version_id INTEGER NOT NULL REFERENCES lick_versions(id) ON DELETE CASCADE,event_index INTEGER NOT NULL,measure_number INTEGER NOT NULL,beat REAL NOT NULL,onset REAL NOT NULL,duration REAL NOT NULL CHECK(duration>0),is_rest INTEGER NOT NULL DEFAULT 0,written_pitch TEXT,sounding_midi INTEGER,octave INTEGER,string_number INTEGER,fret INTEGER,finger INTEGER,articulation TEXT,source_file_id INTEGER REFERENCES source_files(id),source_event_reference TEXT,UNIQUE(version_id,event_index));
CREATE TABLE lick_note_roles(id INTEGER PRIMARY KEY,note_id INTEGER NOT NULL REFERENCES lick_version_notes(id) ON DELETE CASCADE,analytical_system TEXT NOT NULL,chord_degree TEXT,key_degree TEXT,family_degree TEXT,structural_status TEXT,role TEXT,confidence TEXT,UNIQUE(note_id,analytical_system,role));
CREATE TABLE lick_fingerings(id INTEGER PRIMARY KEY,version_id INTEGER NOT NULL REFERENCES lick_versions(id) ON DELETE CASCADE,slug TEXT UNIQUE NOT NULL,instrument TEXT NOT NULL,tuning TEXT NOT NULL,string_set TEXT NOT NULL,position INTEGER,min_fret INTEGER,max_fret INTEGER,fret_span INTEGER,source_or_generated TEXT NOT NULL,accounts_for_b_string_warp INTEGER NOT NULL,review_status TEXT NOT NULL,is_canonical INTEGER NOT NULL DEFAULT 0);
CREATE TABLE lick_fingering_notes(id INTEGER PRIMARY KEY,fingering_id INTEGER NOT NULL REFERENCES lick_fingerings(id) ON DELETE CASCADE,note_id INTEGER NOT NULL REFERENCES lick_version_notes(id) ON DELETE CASCADE,string_number INTEGER NOT NULL,fret INTEGER NOT NULL,finger INTEGER,UNIQUE(fingering_id,note_id));
CREATE TABLE lick_harmonic_analyses(id INTEGER PRIMARY KEY,version_id INTEGER NOT NULL REFERENCES lick_versions(id),analytical_system TEXT NOT NULL,summary TEXT NOT NULL,confidence TEXT NOT NULL,review_status TEXT NOT NULL,UNIQUE(version_id,analytical_system));
CREATE TABLE lick_applications(id INTEGER PRIMARY KEY,version_id INTEGER NOT NULL REFERENCES lick_versions(id),chord_quality TEXT NOT NULL,chord_root_relation TEXT,progression_context TEXT,harmonic_duration REAL,start_beat REAL,end_beat REAL,target_chord TEXT,target_degree TEXT,required_resolution TEXT,analytical_basis TEXT NOT NULL,evidence TEXT NOT NULL,confidence TEXT NOT NULL,review_status TEXT NOT NULL,UNIQUE(version_id,chord_quality,progression_context));
CREATE TABLE lick_entry_states(id INTEGER PRIMARY KEY,version_id INTEGER NOT NULL UNIQUE REFERENCES lick_versions(id),first_pitch TEXT,first_degree TEXT,beat REAL,string_number INTEGER,fret INTEGER,position INTEGER,register_label TEXT,contour TEXT);
CREATE TABLE lick_exit_states(id INTEGER PRIMARY KEY,version_id INTEGER NOT NULL UNIQUE REFERENCES lick_versions(id),final_pitch TEXT,final_degree TEXT,beat REAL,string_number INTEGER,fret INTEGER,position INTEGER,register_label TEXT,resolution_status TEXT,cadence_strength TEXT);
CREATE TABLE lick_phrase_roles(id INTEGER PRIMARY KEY,version_id INTEGER NOT NULL REFERENCES lick_versions(id),role TEXT NOT NULL,confidence TEXT NOT NULL,UNIQUE(version_id,role));
CREATE TABLE lick_transpositions(id INTEGER PRIMARY KEY,version_id INTEGER NOT NULL REFERENCES lick_versions(id),semitones INTEGER NOT NULL,target_key TEXT NOT NULL,pitch_data TEXT NOT NULL,UNIQUE(version_id,semitones));
CREATE TABLE lick_transition_routes(id INTEGER PRIMARY KEY,from_version_id INTEGER NOT NULL REFERENCES lick_versions(id),to_version_id INTEGER NOT NULL REFERENCES lick_versions(id),from_fingering_id INTEGER NOT NULL REFERENCES lick_fingerings(id),to_fingering_id INTEGER NOT NULL REFERENCES lick_fingerings(id),route_type TEXT NOT NULL,raw_fret_distance REAL NOT NULL,adjusted_route_cost REAL NOT NULL,total_score REAL NOT NULL,explanation TEXT NOT NULL,review_status TEXT NOT NULL,UNIQUE(from_version_id,to_version_id,from_fingering_id,to_fingering_id,route_type));
CREATE TABLE lick_transition_components(id INTEGER PRIMARY KEY,route_id INTEGER NOT NULL REFERENCES lick_transition_routes(id) ON DELETE CASCADE,component TEXT NOT NULL,score REAL NOT NULL,explanation TEXT NOT NULL,UNIQUE(route_id,component));
CREATE TABLE lick_reviews(id INTEGER PRIMARY KEY,entity_type TEXT NOT NULL,entity_id INTEGER NOT NULL,decision TEXT NOT NULL,reviewer_notes TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE tune_lick_candidates(id INTEGER PRIMARY KEY,tune_id INTEGER REFERENCES tunes(id),region_label TEXT NOT NULL,version_id INTEGER NOT NULL REFERENCES lick_versions(id),score REAL NOT NULL,explanation TEXT NOT NULL,review_status TEXT NOT NULL);
CREATE VIEW v_lick_catalog AS SELECT f.slug AS family,v.slug AS version,f.degree_pattern,v.key_name,v.meter,v.tempo,v.review_status FROM lick_versions v JOIN lick_families f ON f.id=v.family_id;
CREATE VIEW v_lick_notes AS SELECT v.slug,n.event_index,n.measure_number,n.beat,n.duration,n.written_pitch,n.sounding_midi,n.string_number,n.fret FROM lick_version_notes n JOIN lick_versions v ON v.id=n.version_id;
CREATE VIEW v_lick_fingerings AS SELECT v.slug AS version,f.slug AS fingering,f.instrument,f.tuning,f.string_set,f.min_fret,f.max_fret,f.fret_span,f.source_or_generated,f.review_status FROM lick_fingerings f JOIN lick_versions v ON v.id=f.version_id;
CREATE VIEW v_lick_applications AS SELECT v.slug AS version,a.chord_quality,a.progression_context,a.target_degree,a.confidence,a.review_status FROM lick_applications a JOIN lick_versions v ON v.id=a.version_id;
CREATE VIEW v_lick_entry_exit AS SELECT v.slug,e.first_pitch,e.beat AS entry_beat,e.string_number AS entry_string,e.fret AS entry_fret,x.final_pitch,x.beat AS exit_beat,x.string_number AS exit_string,x.fret AS exit_fret,x.resolution_status FROM lick_versions v JOIN lick_entry_states e ON e.version_id=v.id JOIN lick_exit_states x ON x.version_id=v.id;
CREATE VIEW v_lick_transition_scores AS SELECT a.slug AS from_version,b.slug AS to_version,r.route_type,r.raw_fret_distance,r.adjusted_route_cost,r.total_score,r.explanation,r.review_status FROM lick_transition_routes r JOIN lick_versions a ON a.id=r.from_version_id JOIN lick_versions b ON b.id=r.to_version_id;
CREATE VIEW v_lick_needs_review AS SELECT 'family' AS entity,slug,review_status FROM lick_families WHERE review_status='needs_review' UNION ALL SELECT 'fingering',slug,review_status FROM lick_fingerings WHERE review_status='needs_review';
